import sys,re
def analyze(path):
    d=open(path,'rb').read().decode('utf-8','replace')
    out=[]
    for p in d.split('\r'):
        if p.startswith('Progress'):
            out.append(p.rstrip('\n'))
    return out
def fields(line):
    m=re.match(r'^Progress: (.*?)% words/sec/thread:(.*?) lr:(.*?) avg\.loss:(.*?) ETA:(.*?)h(.*?)m(.*?)s$',line)
    if not m: return None
    return [ (repr(g), len(g)) for g in m.groups() ]
if __name__=='__main__':
    for f in sys.argv[1:]:
        ls=analyze(f)
        print('==',f,'n=',len(ls))
        for l in (ls if len(ls)<=6 else ls[:3]+ls[-3:]):
            print('  ',repr(l))
            print('     ',fields(l))
EOF
